function start(){if(!s.player){set({screen:'login'})}else set({screen:'adventure'})}
function training(){set({screen:'login',trainingMode:true})}
function login(){return `<section class="auth-screen"><div class="auth-backdrop"></div><div class="auth-vignette"></div><button class="auth-back" onclick="go('home')">← <span>ย้อนกลับ</span></button><button class="brand auth-brand" onclick="go('home')"><span class="brand-mark">≋</span><span><b>NAN</b><strong>FLOOD <em>RESCUE</em></strong><small>ภารกิจพิทักษ์เมืองน่าน</small></span></button><div class="auth-steps"><span class="active"><b>1</b>เข้าสู่ระบบ</span><i></i><span><b>2</b>เลือกตัวละคร</span><i></i><span><b>3</b>เริ่มภารกิจ</span></div><div class="auth-panel"><aside class="auth-form-side"><div class="eyebrow">เกมการเรียนรู้สถานการณ์</div><h1>ยินดีต้อนรับ<br>นักเรียนทุกคน</h1><p>เข้าสู่โลกการเรียนรู้ผ่านสถานการณ์จริงของจังหวัดน่าน</p><label>♙ &nbsp;ชื่อนักเรียน<input id="playerName" placeholder="กรอกชื่อนักเรียน" maxlength="24" value="${esc(s.player)}"></label><label>♧ &nbsp;รหัสห้องเรียน <span class="optional">(ถ้ามี)</span><input id="roomCode" placeholder="กรอกรหัสห้องเรียน" maxlength="12" value="${esc(s.room)}"><small>เช่น ป.5/1 หรือ NAN5A</small></label><div class="teacher-note"><b>ⓘ สำหรับครูผู้สอน</b><small>แจกห้องเรียนให้นักเรียนเพื่อเข้าใช้งาน หากไม่มีรหัส ติดต่อผู้ดูแลระบบของโรงเรียน</small></div></aside><div class="auth-avatar-side"><div class="auth-section-title"><span>♙</span><div><h2>เลือกตัวละครของคุณ</h2><p>เลือกบทบาทที่สนใจ แล้วออกไปเรียนรู้และช่วยเหลือจังหวัดน่านไปด้วยกัน</p></div></div><div class="role-grid">${roles.map((r,i)=>`<button class="role ${s.role===i?'active':''}" onclick="pickRole(${i})"><span class="role-portrait avatar-${i}"></span><span class="role-badge">${r[1]}</span><b>${r[0]}</b><small>${r[2]}</small></button>`).join('')}</div><button class="primary auth-continue" onclick="enterGame()">ยืนยันและไปต่อ <span>›</span></button><p class="auth-hint">💡 เลือกตัวละครตามความสนใจ ไม่ส่งผลต่อคะแนน และสามารถเปลี่ยนได้ภายหลัง</p></div></div><p class="auth-disclaimer">ข้อมูลผู้เล่นจะบันทึกในเบราว์เซอร์นี้เท่านั้น จนกว่าจะเชื่อมระบบห้องเรียนออนไลน์</p></section>`}
function pickRole(i){s.role=i;save();render()}
function enterGame(){let v=$('#playerName').value.trim();if(!v){$('#playerName').focus();return}set({player:v,room:$('#roomCode').value.trim().toUpperCase(),screen:'adventure'});}
function adventure(){return `<div id="adventureMount" class="adventure-mount"></div>`}
function mountAdventure(){const host=$('#adventureMount');if(!host||!window.NanAdventure)return;window.NanAdventure.mount(host,{player:s.player,role:s.role,onExit:()=>set({screen:'home'}),onReset:()=>{if(!confirm('เริ่มโลกเกมใหม่และลบความคืบหน้า 3D ในอุปกรณ์นี้?'))return;localStorage.removeItem('nan-adventure-save-v1');render()},onComplete:result=>{s.actions=result?.actions||[];s.budget=result?.budget??s.budget;s.results=[result];s.stage='report';s.screen='game';save();render()}})}
const steps=['brief','explore','plan','sim','survey','recovery','reflect','revise','compare','history','report'];
const stepNames={'brief':'รับภารกิจ','explore':'สำรวจข้อมูล','plan':'วางแผน','sim':'จำลองน้ำ','survey':'สำรวจผล','recovery':'ฟื้นฟูเมือง','reflect':'สะท้อนคิด','revise':'ปรับแผน','compare':'เปรียบเทียบ','history':'เหตุการณ์จริง','report':'รายงาน'};
function game(){return `<div class="game-shell"><aside class="sidebar"><div class="side-title">ภารกิจ 2568 <span>DEMO</span></div><div class="side-sub">พายุวิภา • จังหวัดน่าน</div><div class="phase-list">${steps.map((st,i)=>`<button class="phase ${s.stage===st?'active':''} ${i<steps.indexOf(s.stage)?'done':''}" ${i<=steps.indexOf(s.stage)?`onclick="set({stage:'${st}'})"`:''}><span class="phase-num">${i<steps.indexOf(s.stage)?'✓':i+1}</span><span>${stepNames[st]}</span></button>`).join('')}</div><div class="side-bottom"><div class="budget-label">งบจัดการภัยพิบัติ <button class="q" onclick="tip('budget')">?</button></div><strong>${s.budget} <small>/ 100 หน่วยเกม</small></strong><div class="budget-track"><span style="width:${s.budget}%"></span></div><small>หน่วยทรัพยากรสำหรับฝึกตัดสินใจ ไม่ใช่เงินจริง</small><button class="side-link" onclick="resetGame()">เริ่มภารกิจใหม่</button></div></aside><main class="game-main"><div class="game-head"><div><div class="eyebrow dark">ศูนย์บัญชาการน้ำเมืองน่าน / ${stepNames[s.stage]}</div><h1>${stageTitle()}</h1></div><div class="head-right">${badge('HISTORICAL FACT','fact')}${badge('SIMULATION RESULT','sim')}</div></div>${gameBody()}</main></div>`}
function stageTitle(){return ({brief:'รับข้อมูลก่อนตัดสินใจ',explore:'เดินสำรวจและเก็บข้อมูล',plan:'วางแผนใช้งบของทีม',sim:'ฝนมาแล้ว: ดูผลจำลอง',survey:'ออกสำรวจผลกระทบ',recovery:'ฟื้นฟูเมืองหลังน้ำลด',reflect:'ทีมของเราได้เรียนรู้อะไร',revise:'ลองปรับแผนอีกครั้ง',compare:'เปรียบเทียบสองรอบ',history:'ในเหตุการณ์จริงเกิดอะไรขึ้น',report:'รายงานการเรียนรู้'})[s.stage]}
function gameBody(){if(s.stage==='brief')return brief();if(s.stage==='explore')return explore();if(s.stage==='plan')return plan();if(s.stage==='sim')return sim();if(s.stage==='survey')return survey();if(s.stage==='recovery')return recovery();if(s.stage==='reflect')return reflect();if(s.stage==='revise')return plan(true);if(s.stage==='compare')return compare();if(s.stage==='history')return history();return report()}
function infoStrip(){return `<div class="info-strip"><span>${badge('ข้อมูลจริง','fact')} ${FACT.date}</span><span>พื้นที่: เมืองน่าน • ภูเพียง • เวียงสา</span><a href="${FACT.url}" target="_blank" rel="noopener">ดูแหล่งข้อมูล GISTDA ↗</a></div>`}
function brief(){return `<div class="brief-grid"><div class="card brief-main"><div class="eyebrow dark">ภารกิจ / 25 กรกฎาคม 2568</div><h2>น้ำกำลังเคลื่อนผ่านลุ่มน้ำน่าน</h2><p>ทีมของเธอได้รับข้อมูลอากาศและแผนที่ก่อนเปิดภาพน้ำท่วมจากดาวเทียมจริง ลองสำรวจ ดูแนวโน้ม แล้วเลือกว่าจะใช้งบจำกัดอย่างไร</p><div class="brief-callout"><span class="weather-icon">☁</span><div><b>อิทธิพลพายุวิภา</b><small>กรมอุตุนิยมวิทยารายงานว่าฝนหนักในภาคเหนือช่วงปลายเดือนกรกฎาคม 2568 รวมถึงจังหวัดน่าน</small></div></div>${infoStrip()}<div class="button-row"><button class="primary" onclick="${s.preScore===null?'openQuiz(\'pre\')':'set({stage:\'explore\'})'}">${s.preScore===null?'ทำแบบประเมินก่อน แล้วเปิดแผนที่':'เปิดแผนที่สำรวจ'} →</button><button class="soft" onclick="openQuiz('pre')">ทำแบบประเมินก่อนเรียน 10 ข้อ</button></div></div><div class="card brief-side"><h3>เป้าหมายของทีม</h3><ol class="goal-list"><li>อ่านแผนที่และกราฟข้อมูล</li><li>เลือกมาตรการตามเวลาและงบ</li><li>ดูผลจำลองและสำรวจผลกระทบ</li><li>ปรับแผนแล้วอธิบายเหตุผล</li></ol><div class="mini-note"><b>ข้อสำคัญ</b><p>ค่าฝนและระดับน้ำรายชั่วโมงที่ยังไม่มีหลักฐานยืนยัน จะใช้ตัวอย่างจำลองเท่านั้น</p></div></div></div>`}
function mapPanel(){return `<div class="map-card"><div class="map-toolbar"><div><b>แผนที่จังหวัดน่าน</b><small>แผนที่ฐาน © OpenStreetMap • คลิกจุดเพื่อเดินสำรวจ</small></div><div class="map-controls"><select aria-label="ชั้นข้อมูลแผนที่" onchange="changeLayer(this.value)"><option value="general" ${s.layer==='general'?'selected':''}>แผนที่ทั่วไป</option><option value="terrain" ${s.layer==='terrain'?'selected':''}>ภูมิประเทศ</option><option value="river" ${s.layer==='river'?'selected':''}>แม่น้ำน่าน (OSM)</option><option value="districts" ${s.layer==='districts'?'selected':''}>ขอบเขตอำเภอ (OSM)</option><option value="rain" ${s.layer==='rain'?'selected':''}>ฝน</option><option value="flood" ${s.layer==='flood'?'selected':''}>พื้นที่น้ำท่วมจำลอง</option></select><button onclick="tip('layers')" class="q">?</button></div></div><div id="map"></div><div class="map-bottom"><span>🧍 ${roles[s.role][0]} • แตะจุดบนแผนที่เพื่อเดิน</span><span>${s.stage==='sim'||s.stage==='survey'||s.stage==='compare'?'ชั้นน้ำสีฟ้า = ผลจำลอง':'ตำแหน่งจุดเรียนรู้บางแห่งเป็นตัวอย่างจำลอง'}</span></div></div>`}
function selectedPanel(){let p=places.find(x=>x.id===s.selected)||places[0];let visited=s.visited.includes(p.id);return `<div class="card place-panel"><div class="panel-kicker">จุดสำรวจ ${visited?'✓ สำรวจแล้ว':''}</div><div class="place-icon">${p.icon}</div><h3>${p.name}</h3><small>${p.type}</small><p>${p.detail}</p>${s.role===2?'<div class="role-tip">🧭 คำใบ้: ดูพื้นที่สูงทางเหนือและพื้นที่ลุ่มริมแม่น้ำน่าน</div>':''}${p.id==='station'?`<div class="chart-wrap"><div class="chart-title">แนวโน้มระดับน้ำ ${badge('ข้อมูลจำลอง','sim')}</div>${lineChart()}<small>ตัวเลขกราฟเป็นตัวอย่างเพื่อฝึกอ่าน ไม่ใช่ค่าจริงของสถานี N.1</small>${s.role===1?'<div class="role-tip">🔬 คำใบ้: กราฟนี้กำลังสูงขึ้นต่อเนื่อง ควรติดตามและเตรียมพร้อม</div>':''}</div>`:''}${p.id==='rain'?`<div class="unknown">ปริมาณฝนรายชั่วโมง: <b>ไม่มีข้อมูลยืนยัน</b></div>`:''}<button class="soft full" onclick="visit('${p.id}')">${visited?'อ่านข้อมูลอีกครั้ง':'เก็บข้อมูลจุดนี้'}</button></div>`}
function lineChart(){return `<svg viewBox="0 0 260 110" role="img" aria-label="กราฟตัวอย่างระดับน้ำเพิ่มขึ้นต่อเนื่อง"><path d="M20 90H250M20 55H250M20 20H250" stroke="#dde9ed" stroke-width="1"/><path d="M20 84 L65 78 L110 66 L155 56 L200 38 L245 22" fill="none" stroke="#1686a9" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><g fill="#1686a9"><circle cx="20" cy="84" r="4"/><circle cx="65" cy="78" r="4"/><circle cx="110" cy="66" r="4"/><circle cx="155" cy="56" r="4"/><circle cx="200" cy="38" r="4"/><circle cx="245" cy="22" r="4"/></g><text x="20" y="106">ก่อนฝน</text><text x="188" y="106">ฝนมากขึ้น</text></svg>`}
function explore(){return `<div class="explore-layout">${mapPanel()}<div class="right-stack"><div class="card task-card"><div class="panel-kicker">ภารกิจสำรวจ</div><h3>อ่านข้อมูลก่อนวางแผน</h3><p>เดินไปยังสถานีวัดน้ำ สถานีวัดฝน และอย่างน้อยหนึ่งชุมชน</p><div class="progress-list"><span>${s.visited.includes('station')?'✓':'○'} สถานีวัดน้ำ</span><span>${s.visited.includes('rain')?'✓':'○'} สถานีวัดฝน</span><span>${['nan','phu','wiang'].some(x=>s.visited.includes(x))?'✓':'○'} ชุมชน</span></div><button class="primary full" onclick="set({stage:'plan'})">ไปวางแผน →</button></div>${selectedPanel()}</div></div>`}
function phaseTabs(){return `<div class="phase-tabs"><span>ก่อนฤดูฝน</span><span>ก่อนน้ำมา</span><span>ขณะเกิดเหตุ</span></div>`}
function plan(revise=false){return `<div class="plan-layout"><div class="plan-map">${mapPanel()}<div class="card inventory"><div><b>คลังอุปกรณ์และมาตรการ</b><small>ซื้อแล้วเลือกจุดบนแผนที่เพื่อวาง</small></div><div class="inv-chips">${s.inventory.length?s.inventory.map((id,i)=>{let m=measures.find(x=>x.id===id);return `<button onclick="choosePlacement(${i})" class="inv-chip">${m.icon} ${m.name} <span>วาง ↗</span></button>`}).join(''):'<span class="empty">ยังไม่มีอุปกรณ์ในคลัง</span>'}</div>${s.pending!==null?'<div class="pending-note">เลือกจุดบนแผนที่เพื่อวางมาตรการ • กด Esc เพื่อยกเลิก</div>':''}</div></div><div class="shop-column"><div class="card shop"><div class="panel-kicker">ศูนย์อุปกรณ์ / หน่วยทรัพยากรเกม</div><h3>${revise?'ปรับแผนรอบที่ 2':'เลือกมาตรการ'}</h3><p class="shop-desc">มาตรการขนาดใหญ่ต้องวางล่วงหน้า ไม่สามารถสร้างทันทีตอนน้ำมา</p>${phaseTabs()}<div class="measure-list">${measures.map(m=>`<div class="measure"><span class="measure-icon">${m.icon}</span><div><b>${m.name}</b><small>${m.phase} • ${m.effect}</small></div><button onclick="buy('${m.id}')" ${s.budget<cost(m)?'disabled':''}>${cost(m)} หน่วย</button></div>`).join('')}</div></div><div class="card action-card"><b>มาตรการที่วางแล้ว (${s.actions.length})</b><div class="action-list">${s.actions.length?s.actions.map((a,i)=>{let m=measures.find(x=>x.id===a.id);return `<div><span>${m.icon} ${m.name} <small>ที่ ${a.place||'จุดที่เลือก'}</small></span><button aria-label="ยกเลิก ${m.name}" onclick="removeAction(${i})">×</button></div>`}).join(''):'<span class="empty">ยังไม่ได้วางมาตรการ</span>'}</div><button class="primary full" onclick="runSimulation()">${revise?'เริ่มจำลองรอบที่ 2':'เริ่มจำลองสถานการณ์'} →</button></div></div></div>`}
function cost(m){return Math.max(6,m.cost-((s.role===0&&m.id==='levee')||(s.role===3&&m.id==='forest')||(s.role===4&&m.id==='evacuate')?4:0))}
function buy(id){let m=measures.find(x=>x.id===id);if(s.budget<cost(m))return;s.modal='think:'+id;render()}
function answerThink(id,choice){let m=measures.find(x=>x.id===id);if(choice!==m.correct){s.modal='try:'+id;render();return}s.budget-=cost(m);s.inventory.push(id);s.modal=null;save();render()}
function choosePlacement(i){s.pending=i;render();setTimeout(()=>{if(map)map.resize()},50)}
function removeAction(i){let a=s.actions.splice(i,1)[0];let m=measures.find(x=>x.id===a.id);s.budget+=cost(m);save();render()}
function runSimulation(){if(!s.actions.length&&s.inventory.length) {s.modal='placefirst';render();return}if(!s.actions.length){s.modal='needplan';render();return}s.stage='sim';s.modal=null;save();render();animateSimulation()}
function sim(){let r=s.results[s.round-1];return `<div class="sim-layout"><div class="sim-map">${mapPanel()}<div class="rain-layer ${r?'settled':''}" id="rainAnim"></div><div class="phaser-overlay" id="phaserOverlay"></div><div class="water-animation ${r?'settled':''}"></div><div class="sim-overlay"><div class="sim-time">${r?'T + 24 ชั่วโมง':'T 0 → T + 24 ชั่วโมง'} ${badge('Simulation Timeline','sim')}</div><div class="sim-progress"><span id="simProgress" style="width:${r?100:0}%"></span></div></div></div><div class="right-stack"><div class="card sim-summary"><div class="panel-kicker">ผลจากแบบจำลองเพื่อการเรียนรู้</div><h3>${r?'น้ำลดแล้ว':'กำลังจำลองฝนและทางน้ำ…'}</h3><p>น้ำไหลจากพื้นที่สูง ผ่านลำน้ำสู่พื้นที่ลุ่ม ผลเปลี่ยนตามมาตรการของทีมและเงื่อนไขในเกม</p>${r?`<div class="risk-number"><strong>${r.risk}</strong><span>/ 100<br>ดัชนีความเสี่ยงจำลอง</span></div><div class="indicator"><span>ความปลอดภัยประชาชน</span><b>${r.safety}%</b><i style="width:${r.safety}%"></i></div><div class="indicator"><span>โรงเรียน</span><b>${r.school}%</b><i style="width:${r.school}%"></i></div><div class="indicator"><span>การเดินทาง</span><b>${r.road}%</b><i style="width:${r.road}%"></i></div><button class="primary full" onclick="set({stage:'${s.round===2?'compare':'survey'}'})">${s.round===2?'เปรียบเทียบผลสองรอบ':'เดินสำรวจหลังน้ำลด'} →</button>`:''}</div><div class="card mini-note"><b>อ่านผลให้ถูกประเภท</b><p>คะแนนและพื้นที่สีฟ้าเป็นผลจำลอง ไม่ใช่จำนวนผู้ได้รับผลกระทบจริงในปี 2568</p></div></div></div>`}
function survey(){let r=s.results[s.round-1];return `<div class="explore-layout">${mapPanel()}<div class="right-stack"><div class="card task-card"><div class="panel-kicker">สำรวจหลังน้ำลด</div><h3>เก็บหลักฐานอย่างน้อย 3 จุด</h3><p>ผลกระทบด้านล่างเป็นการจำลองสำหรับการเรียนรู้</p><div class="survey-list">${['nan','school','wiang','hospital'].map((id,i)=>{let p=places.find(x=>x.id===id);let impact=Math.min(95,Math.max(10,r.risk+[2,8,13,4][i]));return `<button onclick="inspect('${id}')" class="survey-row"><span>${p.icon} ${p.name}</span><b>${s.surveyed.includes(id)?'✓ เก็บแล้ว':`ดัชนี ${impact}`}</b></button>`}).join('')}</div><button class="primary full" onclick="nextAfterSurvey()">ไปฟื้นฟูเมือง →</button></div>${selectedPanel()}</div></div>`}

function nextAfterSurvey(){if(s.surveyed.length<3){s.modal='needsurvey';render();return}set({stage:'recovery'})}
const recoveryOptions=[['road','เปิดถนนให้เดินทางได้','🛣️'],['school','ช่วยโรงเรียนกลับมาเรียน','🏫'],['hospital','ดูแลโรงพยาบาล','🏥'],['farm','ฟื้นฟูพื้นที่เกษตร','🌾'],['nature','ฟื้นฟูพื้นที่ธรรมชาติ','🌿']];
function recovery(){return `<div class="recovery-layout"><div class="card"><div class="panel-kicker">RECOVERY PHASE / ผลจำลอง</div><h2>น้ำลดแล้ว เมืองยังต้องการความช่วยเหลือ</h2><p>ทรัพยากรมีจำกัด เลือกงานฟื้นฟูที่สำคัญก่อนอย่างน้อย 2 อย่าง แต่ละงานใช้ 8 หน่วยเกม</p><div class="recovery-options">${recoveryOptions.map(([id,n,icon])=>`<button class="recovery-option ${s.recovery.includes(id)?'active':''}" onclick="chooseRecovery('${id}')"><span>${icon}</span><b>${n}</b><small>${s.recovery.includes(id)?'✓ เลือกแล้ว':'8 หน่วย'}</small></button>`).join('')}</div><button class="primary" onclick="nextAfterRecovery()">กลับศูนย์บัญชาการเพื่อสะท้อนคิด →</button></div><div class="card"><h3>ข้อมูลที่ทีมสำรวจมา</h3><p>ผลกระทบที่เก็บได้ ${s.surveyed.length} จุด</p><div class="evidence">${s.surveyed.map(id=>{let p=places.find(x=>x.id===id);return `<span>${p.icon} ${p.name}</span>`}).join('')}</div><div class="mini-note"><b>ชวนคิด</b><p>การเปิดถนนช่วยการเดินทาง แต่โรงเรียนและโรงพยาบาลก็มีความสำคัญเช่นกัน ทีมต้องอธิบายลำดับที่เลือก</p></div></div></div>`}
function chooseRecovery(id){if(s.recovery.includes(id)){s.recovery=s.recovery.filter(x=>x!==id);s.budget+=8}else if(s.budget>=8){s.recovery.push(id);s.budget-=8}save();render()}
function nextAfterRecovery(){if(s.recovery.length<2){s.modal='needrecovery';render();return}set({stage:'reflect'})}

function inspect(id){s.lastSelected=s.selected;s.selected=id;if(!s.surveyed.includes(id))s.surveyed.push(id);save();render()}
function reflect(){return `<div class="reflect-layout"><div class="card"><div class="panel-kicker">กลับมาที่ศูนย์บัญชาการ</div><h2>ทีมของเราจะปรับอะไร?</h2><p>ดูผลที่เก็บมา แล้วเลือกคำตอบพร้อมอธิบายสั้น ๆ</p><label>ปัญหาหลักที่พบ<select id="problem"><option>ชุมชนริมลำน้ำเสี่ยง</option><option>โรงเรียนต้องการการป้องกัน</option><option>การแจ้งเตือนช้า</option><option>เส้นทางอพยพไม่พร้อม</option></select></label><label>มาตรการที่ช่วยได้มากที่สุด<select id="best">${s.actions.map(a=>{let m=measures.find(x=>x.id===a.id);return `<option>${m.name}</option>`}).join('')||'<option>ยังไม่มีมาตรการ</option>'}</select></label><label>เหตุผลและสิ่งที่อยากเปลี่ยน<textarea id="reason" rows="4" placeholder="เช่น ฉันอยากเตือนชุมชนให้เร็วขึ้น เพราะ…">${esc(s.reflection?.reason||'')}</textarea></label><button class="primary" onclick="saveReflection()">บันทึก แล้วปรับแผนรอบ 2 →</button></div><div class="card reflection-side"><h3>หลักฐานที่มี</h3><p>สำรวจผลกระทบแล้ว ${s.surveyed.length} จุด</p><div class="evidence">${s.surveyed.map(id=>{let p=places.find(x=>x.id===id);return `<span>${p.icon} ${p.name}</span>`}).join('')||'ยังไม่ได้สำรวจ'}</div><div class="mini-note"><b>คำใบ้</b><p>คิดทั้งต้นน้ำ กลางน้ำ ปลายน้ำ และผลที่อาจย้ายไปอีกพื้นที่</p></div></div></div>`}
function saveReflection(){s.reflection={problem:$('#problem').value,best:$('#best').value,reason:$('#reason').value.trim()};s.round=2;s.stage='revise';s.surveyed=[];save();render()}
function compare(){let a=s.results[0],b=s.results[1];if(!a||!b)return `<div class="card"><p>ยังไม่มีผลจำลองครบสองรอบ</p><button onclick="set({stage:'revise'})">กลับไปปรับแผน</button></div>`;let rows=[['ดัชนีความเสี่ยง',a.risk,b.risk,'ค่าน้อยดีกว่า'],['ความปลอดภัยประชาชน',a.safety,b.safety,'ค่ามากดีกว่า'],['โรงเรียน',a.school,b.school,'ค่ามากดีกว่า'],['การเดินทาง',a.road,b.road,'ค่ามากดีกว่า'],['สิ่งแวดล้อม',a.environment,b.environment,'ค่ามากดีกว่า']];return `<div class="compare-layout"><div class="card compare-card"><div class="panel-kicker">ผลจากแบบจำลองเพื่อการเรียนรู้</div><h2>ก่อนและหลังปรับแผน</h2><div class="compare-table"><div class="compare-head"><span>ตัวชี้วัดจำลอง</span><b>รอบ 1</b><b>รอบ 2</b></div>${rows.map(x=>`<div class="compare-row"><span>${x[0]}<small>${x[3]}</small></span><b>${x[1]}</b><b class="${x[2]>x[1]?'up':'down'}">${x[2]}</b></div>`).join('')}</div><p class="helptext">คะแนนเหล่านี้เป็นดัชนีจำลอง 0–100 ไม่ใช่จำนวนคนหรือพื้นที่จริง</p><label>ทำไมผลรอบสองจึงเปลี่ยน?<textarea id="why" rows="3" placeholder="มาตรการใดทำให้ผลต่างไป และอาจกระทบที่ไหนอีก">${esc(s.reflection?.why||'')}</textarea></label><button class="primary" onclick="saveWhy()">บันทึกคำอธิบาย แล้วดูเหตุการณ์จริง →</button></div><div class="card comparison-map">${mapPanel()}</div></div>`}
function saveWhy(){s.reflection={...s.reflection,why:$('#why').value.trim()};set({stage:'history'})}
function history(){return `<div class="history-layout"><div class="card historical"><div class="panel-kicker">เหตุการณ์จริง / HISTORICAL FACT</div><h2>ภาพดาวเทียม ICEYE<br>25 กรกฎาคม 2568</h2><div class="historical-number">22,032 <span>ไร่</span></div><p>GISTDA รายงานพื้นที่น้ำท่วมบางส่วนในอำเภอเมืองน่าน ภูเพียง และเวียงสา</p><div class="district-chips">${FACT.districts.map(x=>`<span>${x}</span>`).join('')}</div><div class="source-box"><b>แหล่งข้อมูล</b><span>${FACT.source} • เผยแพร่ ${FACT.sourceDate}</span><a href="${FACT.url}" target="_blank" rel="noopener">เปิดรายงานและภาพต้นฉบับ ↗</a></div><p class="source-limitation">ยังไม่มีไฟล์พิกัดขอบเขตน้ำท่วมที่ตรวจสอบได้ในต้นแบบ จึงไม่วาดรูปร่างพื้นที่น้ำท่วมจริงทับแผนที่</p></div><div class="card replay"><div class="panel-kicker">ผลจำลองของทีมคุณ</div><h2>แผนของทีมสร้างผลอย่างไร</h2><div class="replay-metric"><strong>${s.results[1]?.risk??s.results[0]?.risk}</strong><span>ดัชนีความเสี่ยงจำลอง / 100</span></div><p>เกมใช้แบบจำลองอย่างง่ายจากพื้นที่ลุ่ม ทางน้ำ การเตือนภัย และมาตรการที่ทีมเลือก จึงไม่สามารถนำไปอธิบายว่าเหตุการณ์จริงจะเปลี่ยนเช่นนี้</p><div class="mini-note"><b>ชวนคิด</b><p>ผลจำลองของทีมใกล้หรือไกลจากข้อมูลจริงในด้านใด? ข้อมูลอะไรที่ต้องมีเพิ่มจึงจะเปรียบเทียบได้ดีขึ้น?</p></div><button class="primary" onclick="set({stage:'report'})">ดูรายงานการเรียนรู้ →</button></div></div>`}
function savePerformance(){s.performanceTask=$('#performanceTask').value.trim();save();render()}
function score(){let adventure=s.results[0]?.modelVersion?.startsWith('adventure'),v=adventure?(s.results[0].survey?.length||0):s.visited.length,a=s.actions.length,re=s.reflection?.reason?.length||0,why=s.reflection?.why?.length||0;if(adventure){const r=s.results[0];return {data:Math.min(20,11+v*3),geo:Math.min(20,10+a*2),problem:Math.min(25,12+a*3+(r.pumpFixed?3:0)),system:Math.min(15,7+(r.schoolEvacuated?4:0)+Math.min(4,a)),budget:Math.min(10,Math.max(4,10-Math.round((100-r.budget)/25))),communication:Math.min(10,3+Math.round((r.trust||30)/16))}}return {data:Math.min(20,8+v*2),geo:Math.min(20,8+Math.min(v,4)*3),problem:Math.min(25,8+a*3+(s.results.length===2?4:0)),system:Math.min(15,5+(s.actions.some(x=>x.id==='levee')?3:0)+(why>10?7:0)),budget:Math.min(10,Math.max(3,10-Math.round((100-s.budget)/25))),communication:Math.min(10,2+(re>10?4:0)+(why>10?4:0))}}
function report(){let sc=score(),total=Object.values(sc).reduce((a,b)=>a+b,0),r=s.results[0],adventure=r?.modelVersion?.startsWith('adventure');return `<div class="report-layout"><div class="card report-hero"><div class="report-check">✓</div><div class="panel-kicker">ภารกิจเสร็จสิ้น</div><h2>${esc(s.player)} กับทีมพิทักษ์เมืองน่าน</h2><p>${adventure?'สำรวจโลก 3D ลงมือวางมาตรการ รับมือเหตุฉุกเฉิน และเก็บหลักฐานความเสียหายครบวงจร':'ทีมใช้ข้อมูลและลองปรับแผน 2 รอบ แล้วเปรียบเทียบผลจำลองกับรายงานเหตุการณ์จริง'}</p><div class="score-total"><strong>${total}</strong><span>/ 100<br>คะแนนการเรียนรู้</span></div><button class="soft" onclick="openQuiz('post')">ทำแบบประเมินหลังเรียน 10 ข้อ</button></div><div class="card skill-scores"><h3>ทักษะที่ได้ฝึก</h3>${[['data','อ่านข้อมูล',20],['geo','คิดจากแผนที่',20],['problem','แก้ปัญหา',25],['system','คิดเป็นระบบ',15],['budget','จัดการงบ',10],['communication','สื่อสารและสะท้อนคิด',10]].map(([k,n,max])=>`<div class="skill-row"><span>${n}</span><b>${sc[k]}/${max}</b><i><em style="width:${sc[k]/max*100}%"></em></i></div>`).join('')}<div class="mini-note"><b>ข้อคิดจากภารกิจ</b><p>ไม่มีมาตรการเดียวที่ใช้ได้ทุกสถานการณ์ ต้องดูข้อมูล พื้นที่ เวลา คน และงบประมาณร่วมกัน</p></div></div><div class="card report-wide"><h3>บันทึกการตัดสินใจ</h3><p>${s.actions.map(a=>measures.find(x=>x.id===a.id)?.name).filter(Boolean).join(' • ')||'ไม่มีมาตรการ'}</p>${adventure?`<h3>หลักฐานภาคสนาม</h3><p>สำรวจ ${r.survey?.length||0}/3 จุด • Community Trust ${r.trust||0} • ${r.xp||0} XP • ${r.schoolEvacuated?'อพยพโรงเรียนสำเร็จ':'ไม่ได้อพยพโรงเรียน'} • ${r.pumpFixed?'ซ่อมเครื่องสูบน้ำสำเร็จ':'ไม่ได้ซ่อมเครื่องสูบน้ำ'}</p>`:`<h3>เหตุผลที่ปรับแผน</h3><p>${esc(s.reflection?.why||'ยังไม่ได้เขียน')}</p>`}<h3>ภารกิจใหม่: ออกแบบแผนของตัวเอง</h3><p>สมมติว่าหมู่บ้านแห่งหนึ่งอยู่ริมลำน้ำ มีโรงเรียนอยู่บนที่สูง และงบจำกัด เธอจะอ่านข้อมูลใดก่อน เตือนใคร และเลือกมาตรการอะไร? เขียนเหตุผลสั้น ๆ</p><textarea id="performanceTask" rows="3" placeholder="แผนของฉัน…">${esc(s.performanceTask||'')}</textarea><button class="soft" onclick="savePerformance()">บันทึกคำตอบ</button><div class="button-row"><button class="soft" onclick="window.print()">พิมพ์รายงาน</button><button class="soft" onclick="start()">กลับเข้าโลกเกม</button><button class="soft" onclick="go('timeline')">ดูภารกิจอื่น</button></div></div></div>`}
function timeline(){return `<section class="content-page"><div class="page-heading"><div class="eyebrow dark">คลังเหตุการณ์</div><h1>เรียนรู้จากน้ำท่วมน่าน</h1><p>มีเพียงภารกิจปี 2568 ที่เล่นได้ในต้นแบบ ข้อมูลปีอื่นรอการตรวจสอบก่อนเผยแพร่</p></div><div class="timeline-grid">${missions.map(m=>`<div class="card mission-card ${m[0]==='2568'?'featured':''}"><div class="mission-year">${m[0]}</div><h2>${m[1]}</h2><p>${m[2]}</p>${m[0]==='2568'?`<button class="primary" onclick="start()">เล่นภารกิจนี้ →</button>`:`<span class="pending-badge">รอข้อมูลยืนยัน</span>`}</div>`).join('')}</div></section>`}
function learn(){return `<section class="content-page learn-page"><div class="page-heading"><div class="eyebrow dark">เรียนรู้จังหวัดน่าน</div><h1>อ่านพื้นที่ ก่อนคิดเรื่องน้ำ</h1><p>ลองดูแผนที่จริง แล้วคิดว่าน้ำจากพื้นที่สูงจะเดินทางสู่พื้นที่ลุ่มอย่างไร</p></div><div class="learn-grid"><div class="card learn-map">${mapPanel()}</div><div class="card"><h2>คำศัพท์สำคัญ</h2>${Object.entries(glossary).filter(x=>x[0]!=='budget'&&x[0]!=='layers').map(([k,v])=>`<button class="glossary-row" onclick="tip('${k}')"><span>${v.title}</span><b>?</b></button>`).join('')}<div class="source-box"><b>แผนที่ฐาน</b><span>© OpenStreetMap contributors</span><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">เงื่อนไขข้อมูลแผนที่ ↗</a></div></div></div></section>`}
const glossary={budget:{title:'งบจัดการภัยพิบัติ',text:'หน่วยทรัพยากรในเกมสำหรับเลือกแผน ไม่ใช่เงินบาทหรือราคาก่อสร้างจริง'},layers:{title:'ชั้นข้อมูลแผนที่',text:'ข้อมูลหลายชนิดที่เปิดดูบนแผนที่ได้ ชั้นน้ำสีฟ้าในเกมคือผลจำลอง ไม่ใช่ขอบเขตน้ำท่วมจริง'},upstream:{title:'ต้นน้ำ',text:'พื้นที่สูงที่น้ำฝนเริ่มไหลลงสู่ลำห้วยและแม่น้ำ'},retention:{title:'พื้นที่รับน้ำ',text:'พื้นที่ที่ยอมให้น้ำพักชั่วคราว เพื่อลดความเร็วหรือปริมาณน้ำในจุดอื่น'},waterlevel:{title:'ระดับน้ำ',text:'ความสูงของผิวน้ำ ณ จุดวัด โดยต้องดูเวลาและหน่วยที่ใช้เสมอ'},rain:{title:'ฝนสะสม',text:'ปริมาณฝนที่รวมในช่วงเวลาหนึ่ง เช่น 24 ชั่วโมง'},flow:{title:'อัตราการไหล',text:'ปริมาณน้ำที่ผ่านจุดหนึ่งในแต่ละช่วงเวลา'}};
function about(){return `<section class="content-page"><div class="page-heading"><div class="eyebrow dark">เกี่ยวกับโครงการ</div><h1>ข้อมูลจริงอยู่ตรงไหน?</h1></div><div class="about-grid"><div class="card"><h2>ข้อมูลเหตุการณ์จริง</h2><p>ภารกิจปี 2568 ใช้รายงาน GISTDA จากภาพดาวเทียม ICEYE วันที่ 25 กรกฎาคม 2568 และข้อมูลสภาพอากาศจากกรมอุตุนิยมวิทยา</p><div class="source-box"><b>GISTDA</b><span>วันที่ข้อมูล 25 ก.ค. 2568 • เผยแพร่ 29 ก.ค. 2568</span><a href="${FACT.url}" target="_blank" rel="noopener">อ่านต้นฉบับ ↗</a></div><div class="source-box"><b>กรมอุตุนิยมวิทยา</b><span>สรุปสภาพอากาศเดือนกรกฎาคม 2568</span><a href="${FACT.tmd}" target="_blank" rel="noopener">อ่านต้นฉบับ ↗</a></div></div><div class="card"><h2>ข้อจำกัดของต้นแบบ</h2><p>กราฟน้ำ จุดโรงเรียนและโรงพยาบาลบางจุด และชั้นน้ำสีฟ้าบนแผนที่เป็นข้อมูลเพื่อการจำลอง ไม่ใช่ข้อมูลประวัติศาสตร์</p><p>เกมนี้จัดทำขึ้นเพื่อการเรียนรู้และฝึกการคิดแก้ปัญหา ผลจากการจำลองไม่ได้ใช้แทนการวิเคราะห์ทางวิศวกรรม การพยากรณ์อุทกภัย หรือคำแนะนำจากหน่วยงานราชการ</p><p>ข้อมูลผู้เล่นในต้นแบบเก็บในเบราว์เซอร์เครื่องนี้ ครูและนักเรียนต่างเครื่องยังไม่เชื่อมต่อกัน</p></div></div></section>`}
function teacher(){return `<section class="content-page teacher-page"><div class="page-heading"><div class="eyebrow dark">สำหรับครู / ตัวอย่าง Dashboard</div><h1>ติดตามการเรียนรู้ของทีม</h1><p>ข้อมูลสาธิตและผลจากอุปกรณ์นี้เท่านั้น</p></div>${!s.teacherLogin?`<div class="card teacher-login"><h2>เข้าสู่หน้าครูตัวอย่าง</h2><p>ใส่รหัส <b>DEMO-ครู</b> เพื่อดูการทำงานของ Dashboard</p><label>รหัสครู<input id="teacherCode" placeholder="DEMO-ครู"></label><button class="primary" onclick="teacherEnter()">เข้าสู่ระบบตัวอย่าง →</button><small>รหัสนี้มีไว้เปิดหน้าสาธิต ไม่ใช่ระบบยืนยันตัวตนจริง</small></div>`:teacherDashboard()}</section>`}
function teacherEnter(){if($('#teacherCode').value.trim()==='DEMO-ครู'){set({teacherLogin:true})}else{alert('รหัสตัวอย่างคือ DEMO-ครู')}}
function teacherDashboard(){let sc=score();let total=Object.values(sc).reduce((a,b)=>a+b,0);return `<div class="teacher-grid"><div class="card teacher-config"><h2>ห้องเรียน</h2><label>รหัสเข้าห้อง<input id="teacherRoom" value="${esc(s.teacherRoom)}" maxlength="12"></label><label>เวลาเล่น (นาที)<input id="teacherTime" type="number" min="10" max="120" value="${s.teacherTime}"></label><label>จำนวนรอบ<select id="teacherRounds"><option value="1" ${s.teacherRounds===1?'selected':''}>1 รอบ</option><option value="2" ${s.teacherRounds===2?'selected':''}>2 รอบ</option></select></label><button class="soft full" onclick="saveTeacher()">บันทึกการตั้งค่า</button><p class="helptext">ภารกิจ: 2568 • พายุวิภา</p></div><div class="card teacher-results"><div class="teacher-title"><h2>ผลการเรียนรู้ในเครื่องนี้</h2><div><button class="soft" onclick="exportCSV()">Export CSV</button><button class="soft" onclick="window.print()">Print Report</button></div></div><div class="table-scroll"><table><thead><tr><th>นักเรียน</th><th>ห้อง</th><th>ด่าน</th><th>อ่านข้อมูล</th><th>อ่านแผนที่</th><th>การตัดสินใจ</th><th>งบ</th><th>Reflection</th><th>รวม</th></tr></thead><tbody><tr><td>${esc(s.player||'ยังไม่มีผู้เล่น')}</td><td>${esc(s.room||s.teacherRoom)}</td><td>2568</td><td>${sc.data}/20</td><td>${sc.geo}/20</td><td>${sc.problem}/25</td><td>${sc.budget}/10</td><td>${esc(s.reflection?.reason||'ยังไม่มี')}</td><td><b>${total}/100</b></td></tr></tbody></table></div><h3>การตัดสินใจของทีม</h3><p>${s.actions.map(a=>measures.find(x=>x.id===a.id)?.name).join(', ')||'ยังไม่มี'}</p><h3>คำตอบสะท้อนคิด</h3><p>${esc(s.reflection?.why||s.reflection?.reason||'ยังไม่มี')}</p><p class="helptext">Dashboard นี้ยังไม่รวบรวมข้อมูลจากอุปกรณ์อื่นหรือรองรับห้องเรียนหลายคนแบบออนไลน์</p></div></div>`}
function saveTeacher(){s.teacherRoom=$('#teacherRoom').value.trim().toUpperCase();s.teacherTime=Number($('#teacherTime').value);s.teacherRounds=Number($('#teacherRounds').value);save();render()}
function exportCSV(){let sc=score(),row=[s.player||'',s.room||s.teacherRoom,'2568',sc.data,sc.geo,sc.problem,sc.system,sc.budget,sc.communication,Object.values(sc).reduce((a,b)=>a+b,0),s.reflection?.reason||''];let csv='\uFEFF'+'นักเรียน,ห้อง,ด่าน,อ่านข้อมูล,อ่านแผนที่,แก้ปัญหา,คิดเป็นระบบ,งบ,สื่อสาร,รวม,Reflection\n'+row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='nan-flood-rescue-report.csv';a.click();URL.revokeObjectURL(a.href)}
const quizPre=[['น้ำจากภูเขามักไหลไปทางใด?','พื้นที่ต่ำ','พื้นที่สูง',0],['แผนที่ช่วยให้ดูอะไร?','ตำแหน่งพื้นที่','รสชาติอาหาร',0],['ฝนสะสม 24 ชั่วโมงหมายถึงอะไร?','ฝนรวมในหนึ่งวัน','ฝนในหนึ่งนาที',0],['ถ้ากราฟระดับน้ำสูงขึ้น ควรทำอะไร?','ติดตามต่อและเตรียมพร้อม','ไม่ต้องสนใจ',0],['ศูนย์พักพิงควรอยู่ที่ใด?','ที่สูงและเข้าถึงได้','ริมตลิ่งต่ำ',0],['ข้อมูลจากแหล่งใดน่าเชื่อถือกว่า?','หน่วยงานที่ระบุวันและวิธีวัด','ข้อความไม่รู้ที่มา',0],['ป่าต้นน้ำช่วยเรื่องใด?','ดูแลดินและทางน้ำ','หยุดฝนทันที',0],['ถ้างบจำกัดควรทำอย่างไร?','จัดลำดับความสำคัญ','ซื้อทุกอย่าง',0],['คำเตือนภัยควรส่งถึงใคร?','ชุมชนที่เสี่ยง','เฉพาะคนเล่นเกม',0],['ผลจำลองคืออะไร?','ผลจากกติกาในเกม','ข้อเท็จจริงที่เกิดขึ้นแล้ว',0]];
const quizPost=[['น้ำไหลจากบริเวณใดสู่บริเวณใด?','ที่สูงสู่ที่ต่ำ','ที่ต่ำสู่ที่สูง',0],['ก่อนวางแนวกั้นน้ำควรดูอะไร?','ทางน้ำและพื้นที่ปลายน้ำ','สีแผนที่อย่างเดียว',0],['กราฟที่สูงขึ้นต่อเนื่องบอกอะไร?','แนวโน้มเพิ่ม','แนวโน้มลด',0],['ตัวเลข 22,032 ไร่ในเกมเป็นข้อมูลใด?','รายงาน GISTDA ปี 2568','ผลจำลองของทีม',0],['ดัชนีความเสี่ยงในเกมเป็นอะไร?','ผลจำลองเพื่อเรียนรู้','จำนวนจริงจากราชการ',0],['ถ้ามีเวลาหลายเดือน มาตรการใดเหมาะ?','ฟื้นฟูป่าต้นน้ำ','ส่งเรือทันที',0],['เมื่อมีคำเตือนภัยควรทำอะไร?','เตรียมและอพยพตามแผน','รอให้ถนนถูกตัด',0],['มาตรการหนึ่งอาจส่งผลต่อพื้นที่อื่นหรือไม่?','อาจส่งผลได้','ไม่มีทาง',0],['ถ้าข้อมูลสองแหล่งไม่ตรงกันควรทำอย่างไร?','แสดงทั้งสองแหล่ง','เลือกตัวเลขที่ชอบ',0],['แผนที่ช่วยวางแผนอย่างไร?','ดูพื้นที่ลุ่มและทางน้ำ','แทนการสำรวจทุกอย่าง',0]];
function openQuiz(type){s.modal='quiz:'+type;s.quizAnswers={};render()}
function answerQuiz(i,v){s.quizAnswers[i]=v;save();render()}
function submitQuiz(type){let q=type==='pre'?quizPre:quizPost;let n=q.reduce((a,x,i)=>a+(s.quizAnswers[i]===x[3]?1:0),0);if(type==='pre')s.preScore=n;else s.postScore=n;s.modal='quizresult:'+type+':'+n;save();render()}
function modal(){if(!s.modal)return '';let m=s.modal;if(m.startsWith('think:')||m.startsWith('try:')){let id=m.split(':')[1],x=measures.find(z=>z.id===id);return `<div class="modal-back" onclick="closeModal(event)"><div class="modal"><button class="modal-close" onclick="set({modal:null})">×</button><div class="panel-kicker">THINK BEFORE BUILD</div><h2>${m.startsWith('try:')?'ลองดูข้อมูลอีกครั้ง':'คิดก่อนเลือกมาตรการ'}</h2><p>${x.quiz}</p><div class="answer-list">${x.choices.map((c,i)=>`<button onclick="answerThink('${id}',${i})">${c}</button>`).join('')}</div><small>คำถามนี้ช่วยให้ใช้ข้อมูลตัดสินใจ ไม่ใช่ข้อสอบแยกจากเกม</small></div></div>`}if(m.startsWith('quiz:')){let type=m.split(':')[1],q=type==='pre'?quizPre:quizPost;return `<div class="modal-back"><div class="modal quiz-modal"><button class="modal-close" onclick="set({modal:null})">×</button><div class="panel-kicker">${type==='pre'?'ก่อนเรียน':'หลังเรียน'} / 10 ข้อ</div><h2>ลองใช้ความรู้ของเรา</h2><div class="quiz-scroll">${q.map((x,i)=>`<div class="quiz-item"><b>${i+1}. ${x[0]}</b><div>${[1,0].map(j=>`<button class="${s.quizAnswers[i]===j?'chosen':''}" onclick="answerQuiz(${i},${j})">${x[j+1]}</button>`).join('')}</div></div>`).join('')}</div><button class="primary full" onclick="submitQuiz('${type}')">ส่งคำตอบ</button></div></div>`}if(m.startsWith('quizresult:')){let z=m.split(':');return `<div class="modal-back"><div class="modal"><button class="modal-close" onclick="set({modal:null})">×</button><h2>ตอบถูก ${z[2]} / 10 ข้อ</h2><p>คะแนนนี้ช่วยให้เห็นพัฒนาการ ไม่ใช่ผลแพ้ชนะ</p><button class="primary" onclick="set({modal:null})">กลับไปภารกิจ</button></div></div>`}if(m==='needsurvey'||m==='needrecovery')return `<div class="modal-back" onclick="closeModal(event)"><div class="modal"><button class="modal-close" onclick="set({modal:null})">×</button><h2>${m==='needsurvey'?'สำรวจให้ครบก่อน':'เลือกงานฟื้นฟูก่อน'}</h2><p>${m==='needsurvey'?'เก็บข้อมูลผลกระทบอย่างน้อย 3 จุด':'เลือกงานฟื้นฟูอย่างน้อย 2 อย่าง แล้วบอกเหตุผลในขั้นต่อไป'}</p><button class="primary" onclick="set({modal:null})">กลับไปทำภารกิจ</button></div></div>`;if(m.startsWith('tip:')){let z=glossary[m.split(':')[1]];return `<div class="modal-back" onclick="closeModal(event)"><div class="modal"><button class="modal-close" onclick="set({modal:null})">×</button><div class="panel-kicker">คำอธิบายภาษานักเรียน</div><h2>${z.title}</h2><p>${z.text}</p><button class="primary" onclick="set({modal:null})">เข้าใจแล้ว</button></div></div>`}return `<div class="modal-back" onclick="closeModal(event)"><div class="modal"><button class="modal-close" onclick="set({modal:null})">×</button><h2>${m==='needplan'?'เลือกมาตรการก่อน':'ยังมีอุปกรณ์ในคลัง'}</h2><p>${m==='needplan'?'ทีมต้องวางมาตรการอย่างน้อยหนึ่งอย่างก่อนจำลอง':'แตะอุปกรณ์ในคลัง แล้วเลือกตำแหน่งบนแผนที่เพื่อวาง'}</p><button class="primary" onclick="set({modal:null})">กลับไปวางแผน</button></div></div>`}
function closeModal(e){if(e.target.classList.contains('modal-back'))set({modal:null})}
function tip(k){s.modal='tip:'+k;render()}
function resetGame(){if(!confirm('เริ่มภารกิจใหม่และลบผลในเครื่องนี้?'))return;let p=s.player,role=s.role,room=s.room,teacherLogin=s.teacherLogin;s={...fresh(),screen:'game',player:p,role,room,teacherLogin};save();render()}
function changeLayer(v){s.layer=v;save();render()}
function visit(id){if(!s.visited.includes(id))s.visited.push(id);s.lastSelected=s.selected;s.selected=id;save();render()}
function circlePolygon(lat,lng,km){const pts=[];for(let i=0;i<=48;i++){const angle=i/48*Math.PI*2;pts.push([lng+km*Math.cos(angle)/(111*Math.cos(lat*Math.PI/180)),lat+km*Math.sin(angle)/111])}return {type:'Feature',geometry:{type:'Polygon',coordinates:[pts]},properties:{}}}
function initMap(id='map',hero=false){
 const el=document.getElementById(id);if(!el||!window.maplibregl)return;
 const tile=s.layer==='terrain'?'https://a.tile.opentopomap.org/{z}/{x}/{y}.png':'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png';
 const attribution=s.layer==='terrain'?'© OpenStreetMap contributors, SRTM | © OpenTopoMap':'© OpenStreetMap contributors';
 const mapObj=new maplibregl.Map({container:el,style:{version:8,sources:{base:{type:'raster',tiles:[tile],tileSize:256,attribution}},layers:[{id:'base',type:'raster',source:'base'}]},center:hero?[100.76,18.85]:[100.77,18.78],zoom:hero?9.2:9.7,interactive:!hero,attributionControl:true});
 if(hero)return mapObj;
 map=mapObj;mapObj.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-left');
 mapObj.on('load',()=>{
  if(s.layer==='districts'){fetch('data/districts-osm.geojson').then(r=>r.json()).then(data=>{if(!mapObj.isStyleLoaded())return;mapObj.addSource('districts',{type:'geojson',data});mapObj.addLayer({id:'district-fill',type:'fill',source:'districts',paint:{'fill-color':'#3b9e7e','fill-opacity':0.13}});mapObj.addLayer({id:'district-outline',type:'line',source:'districts',paint:{'line-color':'#18856f','line-width':2}})}).catch(()=>{})}
  if(s.layer==='river'){fetch('data/nan-river-osm.geojson').then(r=>r.json()).then(data=>{if(!mapObj.isStyleLoaded())return;mapObj.addSource('river',{type:'geojson',data});mapObj.addLayer({id:'river-line',type:'line',source:'river',paint:{'line-color':'#048dba','line-width':4}})}).catch(()=>{})}
  if(s.layer==='rain'){mapObj.addSource('rain-zone',{type:'geojson',data:circlePolygon(19.0,100.75,17)});mapObj.addLayer({id:'rain-zone',type:'fill',source:'rain-zone',paint:{'fill-color':'#1c8cc0','fill-opacity':0.14}})}
  const showFlood=['sim','survey','compare'].includes(s.stage)||s.layer==='flood';
  if(showFlood&&s.results.length){const r=s.results[s.round-1]||s.results[0];let zones=[[18.79,100.78,3.8,'nan'],[18.60,100.72,3,'wiang'],[18.80,100.84,2.6,'phu']];let data={type:'FeatureCollection',features:zones.map(([lat,lng,rad,zone])=>circlePolygon(lat,lng,rad*((r.districtRisks?.[zone]||r.risk)/70)))};mapObj.addSource('simulation-water',{type:'geojson',data});mapObj.addLayer({id:'simulation-water',type:'fill',source:'simulation-water',paint:{'fill-color':'#38b7e9','fill-opacity':0.30}});mapObj.addLayer({id:'simulation-water-edge',type:'line',source:'simulation-water',paint:{'line-color':'#188bb7','line-width':1}})}
 });
 places.forEach(p=>{const el=document.createElement('button');el.className='map-pin '+(s.selected===p.id?'selected':'');el.innerHTML='<span>'+p.icon+'</span>';el.title=p.name;el.setAttribute('aria-label',p.name);el.onclick=e=>{e.stopPropagation();s.lastSelected=s.selected;s.selected=p.id;if(s.pending!==null){let idx=s.pending,mid=s.inventory.splice(idx,1)[0];s.actions.push({id:mid,place:p.name,lat:p.lat,lng:p.lng});s.pending=null}else if(s.stage==='explore'&&!s.visited.includes(p.id))s.visited.push(p.id);save();render()};new maplibregl.Marker({element:el}).setLngLat([p.lng,p.lat]).addTo(mapObj)});
 let av=places.find(p=>p.id===s.selected)||places[0];const avatar=document.createElement('div');avatar.className='avatar-map';avatar.textContent=roles[s.role][1];avatarMarker=new maplibregl.Marker({element:avatar}).setLngLat([av.lng+.006,av.lat+.006]).addTo(mapObj);const from=places.find(p=>p.id===s.lastSelected);if(from&&from.id!==av.id){const start=performance.now();function walk(t){if(map!==mapObj)return;const k=Math.min(1,(t-start)/850);avatarMarker.setLngLat([from.lng+.006+(av.lng-from.lng)*k,from.lat+.006+(av.lat-from.lat)*k]);if(k<1)requestAnimationFrame(walk)}requestAnimationFrame(walk)}
 mapObj.on('click',e=>{if(s.pending!==null){let idx=s.pending,mid=s.inventory.splice(idx,1)[0];let near=places.reduce((a,p)=>Math.abs(p.lat-e.lngLat.lat)+Math.abs(p.lng-e.lngLat.lng)<Math.abs(a.lat-e.lngLat.lat)+Math.abs(a.lng-e.lngLat.lng)?p:a,places[0]);s.actions.push({id:mid,place:near.name,lat:e.lngLat.lat,lng:e.lngLat.lng});s.pending=null;save();render()}});
 return mapObj;
}

function render(){window.FloodAnimation?.stop();window.NanAdventure?.unmount();if(map){map.remove();map=null}app.innerHTML=headerHtml()+(s.screen==='home'?home():s.screen==='login'?login():s.screen==='adventure'?adventure():s.screen==='game'?game():s.screen==='timeline'?timeline():s.screen==='learn'?learn():s.screen==='teacher'?teacher():about())+modal();if($('#map'))initMap();if($('#adventureMount'))mountAdventure();document.onkeydown=e=>{if(e.key==='Escape'&&(s.modal||s.pending!==null)){s.modal=null;s.pending=null;render()}}}
function compute(){return window.SimulationEngine.compute(s.actions,s.budget,measures)}
function animateSimulation(){window.FloodAnimation?.start('phaserOverlay');let n=0,bar=$('#simProgress');let timer=setInterval(()=>{n+=5;if(bar)bar.style.width=n+'%';if(n>=100){clearInterval(timer);s.results[s.round-1]=compute();save();render()}},90)}
render();
